function drawPiplupIcePenguin(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Chân vàng
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.roundRect(-16, by + 28, 9, 8, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(7,   by + 28, 9, 8, 3); ctx.fill();

  // Thân cyan
  ctx.fillStyle = '#7dd3fc';
  ctx.beginPath(); ctx.ellipse(0, by + 14, 18 * sX, 18 * sY, 0, 0, Math.PI * 2); ctx.fill();
  // Khuy áo trắng
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(-5, by + 16, 3, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(5,  by + 16, 3, 0, Math.PI * 2); ctx.fill();

  // Áo choàng
  ctx.fillStyle = '#2563eb';
  ctx.beginPath(); ctx.ellipse(0, by + 2, 22 * sX, 8, 0, 0, Math.PI * 2); ctx.fill();

  // Đầu xanh
  ctx.fillStyle = '#1d4ed8';
  ctx.beginPath(); ctx.arc(0, by - 10, 18 * sX, 0, Math.PI * 2); ctx.fill();

  // Mặt nạ trắng
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.ellipse(0, by - 6, 15 * sX, 9, 0, 0, Math.PI * 2); ctx.fill();

  // Mỏ vàng
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.arc(0, by - 4, 4, 0, Math.PI * 2); ctx.fill();

  // Mắt
  if (!blink) {
    ctx.fillStyle = '#0c4a6e';
    ctx.beginPath(); ctx.ellipse(-7, by - 9, 3, 6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(7,  by - 9, 3, 6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-8, by - 11, 1, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(6,  by - 11, 1, 0, Math.PI * 2); ctx.fill();
  }

  // Cánh
  ctx.fillStyle = '#2563eb';
  ctx.beginPath(); ctx.roundRect(-20, by + 6, 6, 16, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(14,  by + 6, 6, 16, 3); ctx.fill();

  ctx.restore();
}
